"""Temporal candidate policy with safety gating, target hysteresis, and bounded
progress memory.  Motion proposals remain observation-driven and all state is
JSON-serializable.
"""

# EVOLVE-BLOCK-START
MOTION_ACTIONS = ("FORWARD", "VEER_LEFT", "VEER_RIGHT")


def safety_contract(observation, memory):
    """Stop when confidence is low or collision risk is high; otherwise defer."""
    if (
        float(observation.get("safety_confidence", 0.0)) < 0.60
        or float(observation.get("closing_risk", 1.0)) >= 0.75
    ):
        memory["state"] = "STOPPED"
        memory["last_action"] = "STOP"
        return "STOP", 0.99
    return None


def tracking_contract(observation, memory):
    """Require stable target evidence and use stop-before-scan reacquisition."""
    visible = bool(observation.get("target_visible", False))
    reliable = (
        visible
        and float(observation.get("target_confidence", 0.0)) >= 0.55
        and float(observation.get("target_identity_confidence", 0.0)) >= 0.60
    )
    if reliable:
        memory["lost_steps"] = 0
        if int(observation.get("track_age", 0)) < 2:
            memory["state"] = "VERIFY"
            memory["last_action"] = "SLOW_DOWN"
            return "SLOW_DOWN", 0.80
        return None

    lost_steps = int(observation.get("lost_steps", 0))
    prior_state = memory.get("state")
    if prior_state in {"LOCKED", "APPROACH", "REACQUIRE", "VERIFY"} and lost_steps <= 1:
        memory["state"] = "REACQUIRE"
        memory["last_action"] = "STOP"
        return "STOP", 0.92

    direction = memory.get("scan_direction", "SCAN_LEFT")
    memory["scan_direction"] = (
        "SCAN_RIGHT" if direction == "SCAN_LEFT" else "SCAN_LEFT"
    )
    memory["state"] = "SEARCH"
    memory["last_action"] = direction
    return direction, 0.75


def propose_moves(observation, memory):
    """Generate deduplicated moves, prioritizing the currently indicated side."""
    bearing = float(observation.get("target_bearing", 0.0))
    candidates = []

    if bearing < -12.0 and bool(observation.get("corridor_left", False)):
        candidates.append("VEER_LEFT")
    if bearing > 12.0 and bool(observation.get("corridor_right", False)):
        candidates.append("VEER_RIGHT")
    if bool(observation.get("corridor_center", False)):
        candidates.append("FORWARD")
    if bool(observation.get("corridor_left", False)):
        candidates.append("VEER_LEFT")
    if bool(observation.get("corridor_right", False)):
        candidates.append("VEER_RIGHT")

    return list(dict.fromkeys(candidates))


def progress_contract(observation, memory, candidates):
    """Choose a directionally useful move with hysteresis and stagnation escape."""
    if not candidates:
        return None

    bearing = float(observation.get("target_bearing", 0.0))
    previous = memory.get("last_motion")
    distance_class = observation.get("target_distance_class")
    prior_distance = memory.get("previous_distance_class")

    stagnation = int(memory.get("stagnation", 0))
    if prior_distance is not None and distance_class == prior_distance:
        stagnation += 1
    else:
        stagnation = 0
    memory["previous_distance_class"] = distance_class
    memory["stagnation"] = min(stagnation, 3)

    preferred = None
    if bearing < -12.0:
        preferred = "VEER_LEFT"
    elif bearing > 12.0:
        preferred = "VEER_RIGHT"
    elif "FORWARD" in candidates:
        preferred = "FORWARD"

    if preferred in candidates and not (
        preferred != "FORWARD"
        and previous in {"VEER_LEFT", "VEER_RIGHT"}
        and preferred != previous
        and abs(bearing) < 20.0
        and stagnation == 0
    ):
        return preferred

    if stagnation >= 2:
        for option in ("FORWARD", "VEER_LEFT", "VEER_RIGHT"):
            if option in candidates and option != previous:
                return option

    if previous in candidates and (preferred is None or abs(bearing) < 20.0):
        return previous
    return candidates[0]


def termination_contract(observation, memory):
    """Return a safe stationary fallback whenever no motion proposal is admissible."""
    memory["state"] = "STOPPED"
    memory["last_action"] = "STOP"
    return "STOP", 0.98


def decide(observation, memory):
    """Compose safety, tracking, arrival, proposal, and temporal progress policies."""
    memory = dict(memory or {})

    safety = safety_contract(observation, memory)
    if safety is not None:
        return safety[0], safety[1], memory

    tracking = tracking_contract(observation, memory)
    if tracking is not None:
        return tracking[0], tracking[1], memory

    memory["state"] = "LOCKED"
    near = observation.get("target_distance_class") == "near"
    heading_error = abs(float(observation.get("heading_error", 999.0)))
    identity_confidence = float(
        observation.get("target_identity_confidence", 0.0)
    )

    if near and heading_error <= 15.0 and identity_confidence >= 0.80:
        memory["state"] = "ARRIVED"
        memory["last_action"] = "ARRIVED"
        return "ARRIVED", 0.96, memory

    if near:
        bearing = float(observation.get("target_bearing", 0.0))
        if bearing < -2.0 and bool(observation.get("corridor_left", False)):
            candidates = ["VEER_LEFT"]
        elif bearing > 2.0 and bool(observation.get("corridor_right", False)):
            candidates = ["VEER_RIGHT"]
        else:
            candidates = propose_moves(observation, memory)
    else:
        candidates = propose_moves(observation, memory)

    action = progress_contract(observation, memory, candidates)
    if action is None:
        fallback = termination_contract(observation, memory)
        return fallback[0], fallback[1], memory

    memory["state"] = "APPROACH"
    memory["last_motion"] = action
    memory["last_action"] = action
    return action, 0.90, memory


# EVOLVE-BLOCK-END
